// Package web carries the built frontend into the binary.
//
// The dist directory is generated by `npm run build` in go/web and committed,
// which is the trade this package makes: the kernel's `go build` must not need
// node, so the artifact is checked in and `vite` is only needed by whoever
// changes the frontend. A missing dist is a compile error rather than a blank
// window, which is the failure mode worth having.
package web

import (
	"embed"
	"io/fs"
	"mime"
	"net/http"
	"strings"
)

func init() {
	// Go builds its type table from the host's mime.types when one exists: this
	// machine has woff2, a bare container may not, and then the file server
	// sniffs the bytes and answers application/octet-stream. KaTeX's fonts are
	// the first binary assets in dist, so the type is named here instead of
	// inherited from whatever the host happens to know.
	_ = mime.AddExtensionType(".woff2", "font/woff2")
}

//go:embed all:dist
var embedded embed.FS

// Assets is the built site, rooted at the directory index.html lives in.
func Assets() fs.FS {
	sub, err := fs.Sub(embedded, "dist")
	if err != nil {
		// Unreachable: the embed directive above fails the build first.
		panic("web: embedded dist is missing: " + err.Error())
	}
	return sub
}

// Handler serves the built frontend.
//
// Two cache policies, because the two kinds of file age differently: the
// document must be revalidated so a rebuilt binary is not served last week's
// markup, while a hashed asset never changes under its own name and may be kept
// forever.
func Handler() http.Handler {
	assets := Assets()
	files := http.FileServerFS(assets)

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := strings.TrimPrefix(r.URL.Path, "/")
		if path == "" {
			serveIndex(w, r, files, assets)
			return
		}
		if _, err := fs.Stat(assets, path); err != nil {
			// A deep link the single-page app owns: hand it the document and
			// let the router decide, rather than answering 404 for a page the
			// app can draw.
			serveIndex(w, r, files, assets)
			return
		}
		if strings.HasPrefix(path, "assets/") {
			w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
		} else {
			w.Header().Set("Cache-Control", "no-cache")
		}
		files.ServeHTTP(w, r)
	})
}

func serveIndex(w http.ResponseWriter, r *http.Request, _ http.Handler, assets fs.FS) {
	document, err := fs.ReadFile(assets, "index.html")
	if err != nil {
		http.Error(w, "web: index.html is missing from the build", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache")
	_, _ = w.Write(document)
}
